export class GRUtils {

    public static buildNumberArray(arraySize: number, fill: number): number[] {
        const newArray: number[] = [];
        for (let $arrayIndex: number = 0; $arrayIndex < arraySize; $arrayIndex++) {
            newArray.push(fill);
        }
        return newArray;
    }

    public static generateDummyReel(symRangeMin: number, symRangeMax: number, reelLength: number): number[] {
        const reel: number[] = [];
        for (let $reelIndex: number = 0; $reelIndex < reelLength; $reelIndex++) {
            const genSymIndex: number = symRangeMin + Math.round(Math.random() * (symRangeMax - symRangeMin));
            reel.push(genSymIndex);
        }
        return reel;
    }

    public static generateAllDummyReels(symbolRangeMin: number, symRangeMax: number, reelLengths: number[]): number[][] {
        const reels: number[][] = [];
        for (let $reelLengthIndex: number = 0; $reelLengthIndex < reelLengths.length; $reelLengthIndex++) {
            reels.push(this.generateDummyReel(symbolRangeMin, symRangeMax, reelLengths[$reelLengthIndex]));
        }
        return reels;
    }

    public static unanimousStateOf(stateArray: number[]): number {
        const states = [...new Set(stateArray)];
        if (states.length > 1) {
            return NaN;
        }
        return parseInt(states.toString());
    }

    public static fillArrayOrValue(value: number | number[], length: number) {
        return Array.isArray(value) ? value : Array(length).fill(value);
    }
}

export const delay = (ms: number) => new Promise<void>(
    (resolve) => setTimeout(resolve, ms)
);

